static void printVersion(void) {
    printf("%s\n", VERSION_STRING);
}

static void printColumns(void) {
    /* Right-align name in a field of 18 chars, two-space gap is built into the
       fact that we reserve 19 chars total (no - one space really). Observed
       output: "                PID Process/thread ID" => "PID" padded to 19. */
