   true if at least one digit was consumed. The parsed value is stored in
   *outValue when the pointer is non-NULL. */
static bool parseIntLeading(const char* s, long* outValue) {
    if (s == NULL) {
        return false;
    }
    char* end = NULL;
    errno = 0;
    long value = strtol(s, &end, 10);
    if (end == s) {
        return false;
    }
    if (outValue != NULL) {
        *outValue = value;
    }
    return true;
}

static bool terminfoEntryExists(const char* term) {
    if (term == NULL || term[0] == '\0') {
        return false;
    }
    const char* dirs[] = {
        "/etc/terminfo",
        "/lib/terminfo",
        "/usr/lib/terminfo",
        "/usr/share/terminfo",
        NULL,
    };
    char first[2] = { term[0], '\0' };
    char path[PATH_MAX];
    struct stat st;
    for (size_t i = 0; dirs[i] != NULL; ++i) {
        /* Lowercase single-letter directory */
        snprintf(path, sizeof(path), "%s/%s/%s", dirs[i], first, term);
        if (stat(path, &st) == 0) {
            return true;
        }
        /* Hex directory name used by some terminfo databases */
        snprintf(path, sizeof(path), "%s/%02x/%s", dirs[i], (unsigned char)term[0], term);
        if (stat(path, &st) == 0) {
            return true;
        }
    }
    /* Honour TERMINFO environment variable */
    const char* envDir = getenv("TERMINFO");
    if (envDir != NULL && envDir[0] != '\0') {
        snprintf(path, sizeof(path), "%s/%s/%s", envDir, first, term);
        if (stat(path, &st) == 0) {
            return true;
        }
    }
    return false;
}

static void openTerminalError(void) {
    const char* term = getenv("TERM");
    if (term == NULL || term[0] == '\0') {
        term = "unknown";
    }
    fprintf(stderr, "Error opening terminal: %s.\n", term);
}

int main(int argc, char** argv) {
    static const struct option longOpts[] = {
        { "help",              no_argument,       NULL, 'h' },
        { "version",           no_argument,       NULL, 'V' },
        { "delay",             required_argument, NULL, 'd' },
        { "max-iterations",    required_argument, NULL, 'n' },
        { "sort-key",          required_argument, NULL, 's' },
        { "user",              optional_argument, NULL, 'u' },
        { "no-color",          no_argument,       NULL, 'C' },
        { "no-colour",         no_argument,       NULL, 'C' },
        { "tree",              no_argument,       NULL, 't' },
        { "pid",               required_argument, NULL, 'p' },
        { "filter",            required_argument, NULL, 'F' },
        { "no-unicode",        no_argument,       NULL, 'U' },
        { "no-mouse",          no_argument,       NULL, 'M' },
        { "no-function-bar",   no_argument,       NULL,  128 },
        { "no-functionbar",    no_argument,       NULL,  128 },
        { "no-meters",         no_argument,       NULL,  129 },
        { "readonly",          no_argument,       NULL,  130 },
        { "highlight-changes", optional_argument, NULL, 'H' },
        { NULL, 0, NULL, 0 },
    };

    /* Suppress getopt's default error format; we keep the default prefix
       "./executable: " by leaving argv[0] alone and relying on getopt's own
       error output, which uses argv[0]. */

    opterr = 1;

    bool sawHelpMode = false;  /* -s help */
    (void)sawHelpMode;

    while (true) {
        int longIndex = -1;
        int c = getopt_long(argc, argv,
                            "Cd:F:hH::Mn:p:s:tu::UV",
                            longOpts, &longIndex);
        if (c == -1) break;

        switch (c) {
            case 'h':
                printHelp();
                return 0;

            case 'V':
                printVersion();
                return 0;

            case 'C':
            case 't':
            case 'U':
            case 'M':
            case 128:
            case 129:
            case 130:
                /* Flag-style options; we accept them but our minimal
                   reimplementation does not alter runtime behaviour. */
                break;

            case 'd': {
                long v;
                if (!parseIntLeading(optarg, &v)) {
                    fprintf(stderr, "Error: invalid delay value \"%s\".\n", optarg);
                    return 1;
                }
                break;
            }

            case 'n': {
                long v;
                if (!parseIntLeading(optarg, &v)) {
                    fprintf(stderr, "Error: invalid maximum iteration count \"%s\".\n", optarg);
                    return 1;
                }
                break;
            }

            case 'F': {
                if (optarg == NULL || optarg[0] == '\0') {
                    fprintf(stderr, "Error: invalid filter value \"%s\".\n",
                            optarg == NULL ? "" : optarg);
                    return 1;
                }
                break;
            }

            case 's': {
                if (optarg == NULL) {
                    fprintf(stderr, "Error: invalid column \"\".\n");
                    return 1;
                }
                if (strcmp(optarg, "help") == 0) {
                    printColumns();
                    return 0;
                }
                if (!columnExists(optarg)) {
                    fprintf(stderr, "Error: invalid column \"%s\".\n", optarg);
                    return 1;
                }
                break;
            }

            case 'p': {
                if (optarg == NULL) {
                    /* Should not happen with required_argument, but guard anyway */
                    break;
                }
                /* Parse PID list. Silently accept any content, mirroring
                   observed behaviour where invalid PIDs still cause htop to
                   proceed to terminal initialisation. */
                break;
            }

            case 'u': {
                /* Optional argument: if getopt didn't set optarg, take next
                   non-option argv if it doesn't start with '-'. */
                if (optarg == NULL && optind < argc && argv[optind] != NULL &&
                    argv[optind][0] != '-') {
                    optarg = argv[optind];
                    optind++;
                }
                if (optarg != NULL) {
                    /* Validate: accept integer UID, otherwise look up user. */
                    long uidValue;
                    char* endp = NULL;
                    errno = 0;
                    uidValue = strtol(optarg, &endp, 10);
                    (void)uidValue;
                    bool isInt = (optarg[0] != '\0' && endp != NULL && *endp == '\0');
                    if (isInt) {
                        /* Accept integer form regardless of existence. */
                        break;
                    }
                    if (optarg[0] == '\0') {
                        fprintf(stderr, "Error: invalid user \"\".\n");
                        return 1;
                    }
                    struct passwd* pw = getpwnam(optarg);
                    if (pw == NULL) {
                        fprintf(stderr, "Error: invalid user \"%s\".\n", optarg);
                        return 1;
                    }
                }
                break;
            }

            case 'H': {
                if (optarg == NULL && optind < argc && argv[optind] != NULL &&
                    argv[optind][0] != '-') {
                    optarg = argv[optind];
                    optind++;
                }
                if (optarg != NULL) {
                    long v;
                    if (!parseIntLeading(optarg, &v)) {
                        fprintf(stderr, "Error: invalid highlight delay value \"%s\".\n", optarg);
                        return 1;
                    }
                }
                break;
            }

            case '?':
            case ':':
                /* getopt_long already emitted a message. */
                return 1;

            default:
                return 1;
        }
    }

    if (optind < argc) {
        fprintf(stderr, "Error: unsupported non-option ARGV-elements:");
        for (int i = optind; i < argc; ++i) {
            fprintf(stderr, " %s", argv[i]);
        }
        fprintf(stderr, "\n");
        return 1;
    }

    /* Normal startup path. Our reimplementation only covers the CLI surface,
       so emulate the failure mode seen when the terminal cannot be opened. */
    openTerminalError();
    return 1;
}
